#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"; source "${SCRIPT_DIR}/lib/common.sh"; source "${SCRIPT_DIR}/lib/config.sh"; source "${SCRIPT_DIR}/lib/pmtiles.sh"; source "${SCRIPT_DIR}/lib/overview.sh"
OVERVIEW=""; for arg in "$@"; do case "${arg}" in --overview=*) OVERVIEW="${arg#*=}";; --yyyymmdd=*) YYYYMMDD="${arg#*=}";; --workdir=*) WORKDIR="${arg#*=}";; -h|--help) printf 'usage: %s --overview=<id> [--yyyymmdd=YYYYMMDD] [--workdir=<path>]\n' "$0"; exit 0;; *) die "${HUAVD_EXIT_INPUT}" "unknown argument: ${arg}";; esac; done
[[ -n "${OVERVIEW}" ]] || die "${HUAVD_EXIT_INPUT}" "--overview is required"; validate_yyyymmdd "${YYYYMMDD}"; require_cmd jq stat; overview_validate "${OVERVIEW}"
pmtiles="$(overview_pmtiles_path "${OVERVIEW}" "${YYYYMMDD}")"; require_file "${pmtiles}"; stage="$(overview_staging_dir "${OVERVIEW}" "${YYYYMMDD}")"; fingerprint="$(< "${stage}/merge-fingerprint")"; composition="$(jq . "$(overview_merge_cache_dir "${OVERVIEW}")/${fingerprint}.json")"; params="$(overview_params "${OVERVIEW}")"; max_zoom="$(pmtiles_max_zoom "${pmtiles}")"
jq -n --arg schema huavd-map-build/v1 --arg overview "${OVERVIEW}" --arg yyyymmdd "${YYYYMMDD}" --arg build_id "$(timestamp_utc)" --arg output_path "outputs/$(basename "${pmtiles}")" --argjson output_size "$(stat -c %s "${pmtiles}")" --arg sha512 "$(sha512_value "${pmtiles}")" --argjson min_zoom "$(pmtiles_min_zoom "${pmtiles}")" --argjson max_zoom "${max_zoom}" --argjson bounds "$(pmtiles_bounds "${pmtiles}")" --argjson layers "$(overview_layers_json "${OVERVIEW}")" --argjson tippecanoe "${params}" --argjson composition "${composition}" --arg fingerprint "${fingerprint}" --arg id "$(overview_get huavd.id "${OVERVIEW}")" --arg source_id "$(overview_get huavd.source_id "${OVERVIEW}")" --arg style_id "$(overview_get huavd.style_id "${OVERVIEW}")" --arg package_version "$(overview_get huavd.package_version_template "${OVERVIEW}" | sed "s/{yyyymmdd}/${YYYYMMDD}/g")" '{schema:$schema,overview:$overview,yyyymmdd:$yyyymmdd,build_id:$build_id,source:{vendor:"geofabrik",source_type:"osm-pbf",composition:($composition + {method:"osmium-merge",fingerprint:$fingerprint})},tools:{osmium:"osmium",tippecanoe:"tippecanoe",pmtiles:"pmtiles"},tippecanoe:$tippecanoe,output:{path:$output_path,size_bytes:$output_size,sha512:$sha512,tile_range:{min_zoom:$min_zoom,max_zoom:$max_zoom,bounds:$bounds}},vector_layers:$layers,huavd_record:{id:$id,name:($overview + ".overview"),source_id:$source_id,asset_role:"overview-vector",source_type:"osm-pbf",package_version:$package_version,transport:"offline",coord_system:"EPSG:3857",style_id:$style_id,format:"pmtiles"},license:{data_license:"ODbL-1.0",attribution:"© OpenStreetMap contributors"}}' > "$(overview_manifest_path "${OVERVIEW}" "${YYYYMMDD}")"
